let locale=localStorage.getItem('lingua-strategies-language')==='zh'?'zh':'en';
const needs=[
  {label:'Make a text accessible',query:'Comprehension',icon:'¶'},
  {label:'Get students talking',query:'Speaking',icon:'“'},
  {label:'Teach vocabulary',query:'vocabulary',icon:'Aa'},
  {label:'Support writing',query:'Writing',icon:'✎'},
  {label:'Scaffold a complex task',query:'scaffold',icon:'↗'},
  {label:'Check understanding',query:'check understanding',icon:'✓'},
  {label:'Support a newcomer',query:'visual',icon:'◎'},
  {label:'Use home languages',query:'multilingual',icon:'文'},
  {label:'Co-teach effectively',query:'model',icon:'↔'},
  {label:'Build independence',query:'Independence',icon:'→'}
];

const deepContent={
  'teach-vocabulary-using-gestures-and-actions':{promise:'Make new words memorable by connecting meaning, movement, and spoken language.',time:10,domains:['Listening','Speaking'],phase:'Before',when:'When a word describes an action, process, direction, feeling, or concept that can be represented physically.',steps:['Choose a small number of useful words.','Say and explain one word in context.','Model a clear gesture linked to its meaning.','Have students say the word and use the gesture in a sentence.','Reuse the gesture when the word returns.'],script:'“This gesture means expand—watch my hands move apart. Say the word, show the movement, then explain what is expanding.”',mistake:'Adding playful movements that are memorable but do not actually clarify meaning.',try:'Choose two words from tomorrow’s lesson and design one meaning-based gesture for each.',why:'Combining spoken language with meaningful physical representation creates multiple routes for recalling and using a new word.'},
  'model-a-picture-walk-before-reading':{promise:'Help learners anticipate a text’s meaning and language before decoding every sentence.',time:10,domains:['Listening','Speaking','Reading'],phase:'Before',when:'Before an illustrated narrative, textbook section, diagram-rich article, or other text with meaningful visual information.',steps:['Preview the title and a few carefully chosen visuals.','Model one observation and one inference.','Invite students to notice details with a partner.','Record a few predictions or questions.','Read to confirm, revise, or extend those ideas.'],script:'“I notice the river is wider here. I wonder whether the weather changed. What do you notice, and what might it mean?”',mistake:'Using the pictures to tell students the entire text instead of creating a purpose for reading.',try:'Select three visuals from tomorrow’s text and prepare one notice-and-wonder prompt.',why:'Visual previewing activates knowledge and supplies context that supports comprehension while preserving authentic reasons to read.'},
  'think-aloud-while-reading-a-text':{promise:'Make the invisible decisions of a proficient reader visible and learnable.',time:10,domains:['Listening','Reading'],phase:'During',when:'When students need to see how a reader monitors meaning, handles confusion, makes an inference, or uses text evidence.',steps:['Choose one specific reading process to model.','Select a short passage where that process matters.','Read, pause, and name your thinking briefly.','Point to the textual or visual clue that prompted it.','Let students try the same move on the next section.'],script:'“That sentence did not make sense to me, so I reread the line before it and noticed the word however. Now I’m revising my idea.”',mistake:'Narrating every thought until the model becomes longer and harder than the text.',try:'Mark one sentence where you will pause and model a single comprehension decision.',why:'A concise think-aloud externalizes expert processes so learners can notice, name, and gradually use them independently.'},
  'check-understanding-with-quick-response-routines':{promise:'See what every learner understands before deciding what to do next.',time:5,domains:['Listening','Speaking','Reading','Writing'],phase:'During',when:'After an explanation, model, text section, or task direction when a volunteer answer would reveal too little.',steps:['Ask one question closely tied to the learning goal.','Choose a response mode everyone can use.','Give quiet thinking time.','Have students respond simultaneously or in a rapid sequence.','Scan responses and adjust, regroup, or continue.'],script:'“Show your answer at the same time. I’m looking for what we understand as a class, not who is fastest.”',mistake:'Asking “Does everyone understand?” or relying on one confident volunteer.',try:'Plan one all-student check using fingers, mini-whiteboards, a sketch, or a one-sentence response.',why:'Broad response routines produce more representative evidence and allow teaching decisions before misconceptions become embedded.'},
  'highlight-cognates-and-cross-language-word-connections':{promise:'Use knowledge students already possess across languages to unlock new vocabulary.',time:10,domains:['Speaking','Reading','Writing'],phase:'Before',when:'When a key word has a useful cognate, shared root, translation connection, or meaningful contrast across students’ languages.',steps:['Identify a genuine cross-language connection.','Invite students to share related words they know.','Compare meaning, form, pronunciation, and use.','Flag false cognates or important differences carefully.','Add the connection to a class word resource.'],script:'“In Spanish, información looks and means something similar to information. What stays the same? What changes when we say it in English?”',mistake:'Assuming all multilingual students know the same language or that similar-looking words always share meaning.',try:'Find one useful cognate or shared root in tomorrow’s key vocabulary and invite students to investigate it.',why:'Cross-language connections position multilingual knowledge as an asset and can accelerate vocabulary recognition and depth.'},
  'recast-student-language-without-interrupting-meaning':{promise:'Offer a more conventional language model while keeping the student’s idea and confidence intact.',time:5,domains:['Listening','Speaking'],phase:'During',when:'During meaningful conversation when a learner’s message is clear but a brief reformulation would support language growth.',steps:['Listen first for the intended meaning.','Respond naturally to the idea.','Restate the message using the target form.','Keep the exchange moving rather than demanding repetition every time.','Notice whether the learner takes up the form later.'],script:'Student: “Yesterday he go home.” Teacher: “Yes, he went home early yesterday. What happened next?”',mistake:'Correcting every error or using a recast so pointedly that it interrupts communication.',try:'Choose one language feature to listen for tomorrow and recast it naturally during a real exchange.',why:'A responsive recast supplies comprehensible language feedback within meaningful interaction without shifting all attention from ideas to errors.'},
  'use-say-it-another-way-prompts':{promise:'Build flexibility by helping students express the same meaning with different words or structures.',time:5,domains:['Listening','Speaking'],phase:'During',when:'When students need clarification, precision, paraphrasing practice, or another route around a missing word.',steps:['Acknowledge the original meaning.','Ask for another way to communicate it.','Offer think time, a gesture, or a key word if needed.','Invite a partner version when useful.','Compare how the versions express the same idea.'],script:'“I understand your idea. Can you say it another way—as if you were explaining it to someone younger?”',mistake:'Using the prompt as a disguised correction after every nonstandard sentence.',try:'Use the prompt once tomorrow when an idea would benefit from greater clarity or precision.',why:'Paraphrasing develops linguistic flexibility and helps learners see that effective communication rarely depends on one perfect sentence.'},
  'teach-discussion-roles':{promise:'Give every group member a meaningful responsibility for building the conversation.',time:10,domains:['Listening','Speaking'],phase:'Before',when:'Before small-group reasoning, text discussion, collaborative inquiry, or decision-making where participation tends to be uneven.',steps:['Choose roles that serve the thinking, not classroom management alone.','Explain and model what each role sounds like.','Give students a short language support for their responsibility.','Rotate roles so no learner becomes fixed in one position.','Debrief how the roles affected the quality of discussion.'],script:'“The connector links two ideas. You might ask, ‘How does this relate to…?’ Your job is to help the group see a relationship.”',mistake:'Assigning passive or status-heavy roles that leave one student doing the intellectual work.',try:'Use three roles tomorrow: explain, connect, and question. Rotate after one round.',why:'Well-designed roles make the hidden work of collaborative dialogue explicit and distribute intellectual responsibility.'},
  'use-visual-discussion-supports':{promise:'Keep ideas, relationships, and participation language visible while students talk.',time:10,domains:['Listening','Speaking','Reading'],phase:'During',when:'During discussion involving several concepts, a sequence, contrasting positions, or unfamiliar conversational routines.',steps:['Identify what students need to see while speaking.','Create one uncluttered visual support.','Model how to refer to it in a response.','Place it where all participants can access it.','Remove or simplify it as the routine becomes familiar.'],script:'“Use the diagram to point to the part you mean. You can begin, ‘This connects to…’”',mistake:'Displaying so many prompts, icons, and words that the support increases cognitive load.',try:'Create one small visual for tomorrow’s discussion: a sequence, concept map, or three conversational moves.',why:'Visible supports reduce memory and word-retrieval demands, leaving more attention available for listening and reasoning.'},
  'model-pronunciation-when-it-supports-communication':{promise:'Support intelligibility and confidence without treating accent difference as a problem.',time:5,domains:['Listening','Speaking'],phase:'During',when:'When pronunciation affects understanding of a high-use word, key distinction, presentation phrase, or classroom interaction.',steps:['Confirm the learner’s intended meaning first.','Choose one feature that will improve intelligibility.','Model the word or phrase naturally in context.','Let students notice and try without public pressure.','Return immediately to meaningful communication.'],script:'“This word is record as a noun and record as a verb. Listen to where the stress moves. Try it in your sentence.”',mistake:'Correcting accent features that do not interfere with meaning or asking learners to erase their linguistic identity.',try:'Identify one genuinely useful pronunciation feature in tomorrow’s content and model it briefly in a phrase.',why:'Selective, contextual pronunciation teaching supports comprehensibility while respecting the legitimacy of diverse accents.'},
  'invite-and-value-multilingual-contributions':{promise:'Make students’ full linguistic repertoires visible as resources for learning and belonging.',time:10,domains:['Listening','Speaking','Reading','Writing'],phase:'During',when:'When generating ideas, building vocabulary, making connections, solving problems, or reflecting on language.',steps:['Explicitly invite thinking or contributions in any language.','Provide a way to share through peers, notes, translation, or explanation.','Show genuine interest in similarities and differences.','Connect the contribution to the class learning.','Record useful multilingual knowledge where the class can revisit it.'],script:'“How might you express this idea in another language you know? What does that help us notice about the meaning?”',mistake:'Inviting home languages only for celebration while excluding them from serious academic thinking.',try:'Add one multilingual invitation to tomorrow’s lesson and plan how the contribution can inform the whole class.',why:'Using the full linguistic repertoire supports meaning-making and communicates that multilingualism is intellectual capital, not an obstacle.'},
  'preview-key-vocabulary-with-visuals':{promise:'Make an unfamiliar text or topic easier to enter—without pre-teaching every word.',time:10,domains:['Listening','Speaking','Reading'],phase:'Before',when:'Before a text, demonstration, or lesson containing a few words students genuinely need in order to participate.',steps:['Choose 3–5 essential words—not every unfamiliar word.','Pair each word with a clear image, object, gesture, or quick sketch.','Say the word in a meaningful sentence, then invite students to repeat or rehearse it.','Ask students to connect the word to the image, an example, or a home-language equivalent.','Keep the words visible and return to them during the lesson.'],script:'“You’ll see this word in today’s text. Look at the image. What do you notice? Turn to a partner and use the word once.”',mistake:'Turning the preview into a long vocabulary lecture. Keep it brief and let the main lesson give the words meaning.',try:'Choose three make-or-break words from tomorrow’s lesson and find one useful visual for each.',why:'A small amount of focused language support reduces the access barrier while preserving the thinking and complexity of the task.'},
  'build-background-knowledge-before-reading':{promise:'Give learners enough shared context to make sense of a challenging text.',time:10,domains:['Listening','Speaking','Reading'],phase:'Before',when:'When a text assumes cultural, historical, or topic knowledge that some learners may not yet share.',steps:['Identify the one piece of knowledge the text assumes.','Show a short visual, map, object, or 60-second explanation.','Invite learners to share related experiences or knowledge in any language.','Record two or three useful ideas or words.','Set a purpose for reading that connects to the preview.'],script:'“Before we read, here is one idea that will help the text make sense. What does this connect to for you?”',mistake:'Explaining the whole text in advance. Build a bridge, but leave something meaningful for students to discover.',try:'Find one image that supplies the missing context for tomorrow’s reading. Plan one connection question.',why:'Comprehension depends on connecting new information to existing knowledge. A brief, inclusive preview makes more connections possible.'},
  'pair-a-language-objective-with-the-content-objective':{promise:'Make the language students need to use as visible as the content they need to learn.',time:5,domains:['Listening','Speaking','Reading','Writing'],phase:'Before',when:'During planning, especially when students understand a concept but struggle to explain, discuss, or write about it.',steps:['Name the content learning clearly.','Identify what students must do with language to show that learning.','Write one observable language objective using a verb such as explain, compare, justify, or describe.','Share both objectives in student-friendly language.','Return to them during the lesson and reflection.'],script:'“Today we are learning why habitats change. We will show that learning by explaining one cause and one effect using because.”',mistake:'Writing a language objective that is too broad, such as “use academic vocabulary.” Name the actual language action.',try:'Add one sentence to tomorrow’s objective: “We will show our learning by…”',why:'Naming the language demand helps teachers plan access and gives learners a clearer target for successful participation.'},
  'pause-for-turn-and-talk-with-sentence-stems':{promise:'Give every learner protected rehearsal time before whole-class discussion.',time:5,domains:['Listening','Speaking'],phase:'During',when:'Before asking for public responses, especially when a question requires explanation or new academic language.',steps:['Ask one clear, worthwhile question.','Display one optional stem that supports the thinking.','Give silent thinking time before partners begin.','Assign who starts and set a short time limit.','Listen in, then invite several ideas into the whole-class conversation.'],script:'“First, think quietly. Then Partner A begins: ‘I think ___ because ___.’ Partner B, listen and build on the idea.”',mistake:'Using a stem as a fill-in-the-blank test. Keep it optional and focused on opening up fuller ideas.',try:'Choose tomorrow’s most important question. Add 10 seconds of think time and one useful sentence stem.',why:'Private rehearsal lowers the risk of speaking publicly and increases the number and quality of ideas available to the class.'},
  'use-wait-time-intentionally':{promise:'Create the thinking space multilingual learners need before they speak.',time:5,domains:['Listening','Speaking'],phase:'During',when:'After posing a question and after a learner begins responding.',steps:['Ask the question once, clearly.','Pause for at least five quiet seconds.','Keep your body language open and resist rephrasing too quickly.','After a response, pause again before evaluating or calling on someone else.','Let students jot or rehearse when the language demand is high.'],script:'“Take your time. I’m giving everyone a few quiet seconds to build an answer.”',mistake:'Filling silence with hints or calling on the fastest speaker. The pause is part of the support.',try:'Mark one question in tomorrow’s plan with “5 seconds” and actually count silently.',why:'Formulating an idea in an additional language takes time. Predictable pauses widen participation without reducing cognitive demand.'},
  'chunk-long-teacher-directions-into-smaller-steps':{promise:'Help students begin independently instead of getting lost in a long string of instructions.',time:5,domains:['Listening','Reading'],phase:'During',when:'Before a multi-step task, transition, practical activity, or unfamiliar routine.',steps:['Identify the first action students need to take.','Say and display only one or two steps at a time.','Model the first step or show the finished shape of the task.','Ask a student to restate what happens first.','Release the next chunk when most students are ready.'],script:'“For now, do just these two things: underline the claim, then circle one reason. Tell your partner what comes first.”',mistake:'Simplifying the learning instead of simplifying access to the directions.',try:'Rewrite one long set of directions as three short numbered chunks. Reveal them progressively.',why:'Reducing the listening and memory load frees attention for the real thinking the task requires.'},
  'use-oral-rehearsal-before-writing':{promise:'Let students hear and refine an idea before asking them to write it.',time:10,domains:['Speaking','Writing'],phase:'During',when:'Before independent writing, especially when students have ideas but struggle to begin or organize them in English.',steps:['Give a focused writing prompt or sentence goal.','Offer a helpful structure, model, or key words.','Ask students to say their sentence to a partner.','Invite the partner to ask one clarifying question.','Have students say the improved version once more, then write.'],script:'“Say your first sentence before you write it. Your partner’s job is to listen and ask, ‘Can you tell me more about…?’”',mistake:'Treating rehearsal as casual chat with no connection to the writing students will produce.',try:'Build a 90-second “say it, improve it, write it” pause into tomorrow’s writing task.',why:'Oral rehearsal makes composing visible and revisable before spelling, handwriting, and syntax add extra demands.'},
  'deconstruct-a-mentor-text':{promise:'Show students how a successful text works so they can make deliberate choices in their own writing.',time:20,domains:['Reading','Writing','Speaking'],phase:'Before',when:'Before students write in an unfamiliar genre or need to improve a particular feature of their writing.',steps:['Choose a short, achievable example of the target genre.','Read first for meaning and purpose.','Name one feature to investigate—not everything at once.','Highlight where the writer uses that feature and discuss its effect.','Co-create a short “we noticed” list students can use while writing.'],script:'“Let’s read this as writers. Where does the author help us understand the sequence? What could we borrow—not copy—for our own writing?”',mistake:'Color-coding many features without discussing what they do for the reader.',try:'Select six useful sentences from a model. Ask students to notice just one feature that tomorrow’s writing needs.',why:'Making the hidden choices of a genre visible gives learners a meaningful model without reducing writing to a formula.'},
  'build-a-shared-word-bank':{promise:'Put useful, precise language within reach during speaking and writing.',time:10,domains:['Speaking','Reading','Writing'],phase:'During',when:'As a class develops ideas for a topic, discussion, investigation, or writing task.',steps:['Start with the communicative task, not an isolated list.','Invite words students already know, including home-language connections.','Add a small number of high-value words from the lesson.','Organize words by meaning or purpose, not alphabetically.','Keep the bank visible and actively prompt students to choose from it.'],script:'“Which words will help us compare these two ideas? Add a word you know in another language if it helps us make the connection.”',mistake:'Creating a large decorative list that students are never taught to use.',try:'Make a three-column word bank for tomorrow: describe, compare, explain.',why:'A shared bank reduces word-retrieval load and turns classroom language into a collective, growing resource.'},
  'color-code-parts-of-a-paragraph':{promise:'Make paragraph structure visible so students can notice how ideas are organized.',time:15,domains:['Reading','Writing'],phase:'During',when:'When students are learning how a paragraph develops a claim, explanation, sequence, comparison, or evidence.',steps:['Choose a short paragraph that serves the target purpose well.','Read it first for meaning.','Assign colors to two or three functional parts.','Discuss what each part does for the reader.','Use the same colors to plan or review student writing.'],script:'“Blue shows the main idea; green shows how the writer develops it. What job is this sentence doing?”',mistake:'Coloring every sentence mechanically without connecting the colors to meaning and purpose.',try:'Color-code one model paragraph using no more than three functions, then discuss why each part matters.',why:'Visual patterning can reduce abstraction and help learners recognize the functional organization of extended writing.'},
  'model-sentence-combining':{promise:'Help students create more precise and fluent sentences from ideas they already understand.',time:10,domains:['Speaking','Reading','Writing'],phase:'During',when:'When student writing contains short related sentences or when a content relationship needs clearer expression.',steps:['Start with two or three meaningful short sentences.','Name the relationship between the ideas.','Think aloud while combining them.','Compare several correct versions and their effects.','Let students combine a new set and explain their choice.'],script:'“These ideas show cause. I could join them with because, so, or as a result—but each choice shapes the sentence differently.”',mistake:'Treating the longest sentence as the best sentence or teaching combination without meaning.',try:'Take two sentences from tomorrow’s content and model two ways to combine them.',why:'Sentence combining develops syntactic flexibility through purposeful choices rather than isolated grammar correction.'},
  'use-sentence-frames-strategically':{promise:'Provide enough language structure for participation without scripting students’ thinking.',time:10,domains:['Speaking','Writing'],phase:'During',when:'When learners understand the concept but an unfamiliar language pattern blocks them from expressing it.',steps:['Identify the language function the task requires.','Write a frame that opens space for substantive choices.','Model one authentic completion.','Offer word resources separately when needed.','Observe use and plan when to loosen or remove the frame.'],script:'“One factor that influenced ___ was ___ because ___. The frame holds the relationship; your evidence and reasoning are your own.”',mistake:'Using frames with only one possible answer or leaving them in place after students no longer need them.',try:'Create one frame for tomorrow’s hardest language function and check that students still supply the important thinking.',why:'A well-designed frame temporarily reduces syntactic demand while preserving conceptual ownership and cognitive challenge.'},
  'move-from-sentence-frames-to-sentence-starters':{promise:'Fade language support deliberately so students gain flexibility and independence.',time:10,domains:['Speaking','Writing'],phase:'During',when:'When students use a full frame successfully and are ready to make more choices about sentence construction.',steps:['Identify which part of the frame students now control.','Replace the full frame with two or three possible openings.','Model how different starters lead to different structures.','Invite students to adapt a starter or write independently.','Notice who still benefits from the original support.'],script:'“Last time the whole sentence was provided. Today choose an opening—‘One reason…,’ ‘This suggests…,’ or your own.”',mistake:'Removing support for the whole class at once rather than responding to readiness.',try:'Turn one familiar full frame into three optional sentence starters for tomorrow.',why:'Gradual release expands linguistic choice while maintaining an accessible bridge for learners who still need it.'},
  'teach-transition-words-explicitly':{promise:'Help students show relationships between ideas instead of merely adding linking words.',time:10,domains:['Reading','Writing'],phase:'During',when:'When learners need to express sequence, contrast, cause, example, addition, or conclusion more clearly.',steps:['Begin with the relationship between ideas.','Study two or three transitions that express it.','Compare their placement and nuance in real sentences.','Have students choose a transition and justify the choice.','Revisit transitions during revision rather than only drafting.'],script:'“These ideas contrast. However and on the other hand both signal contrast, but which fits this sentence best?”',mistake:'Giving students a long categorized list and rewarding transitions regardless of whether the relationship makes sense.',try:'Teach three transitions for one relationship in tomorrow’s writing and compare their effects.',why:'Connecting transitions to logical relationships supports coherence and prevents them from becoming decorative vocabulary.'},
  'model-planning-before-writing':{promise:'Show students how writers develop and organize ideas before composing sentences.',time:15,domains:['Speaking','Writing'],phase:'Before',when:'Before a substantial response, paragraph, explanation, narrative, or unfamiliar genre.',steps:['Clarify the purpose and audience.','Think aloud while generating possible ideas.','Select ideas that best serve the purpose.','Organize them using a simple planning format.','Show that plans can change once writing begins.'],script:'“I have four ideas, but this one answers the question most directly. I’ll place it first and save this detail for later.”',mistake:'Presenting planning as a neat form to complete rather than a decision-making process.',try:'Model three minutes of messy but purposeful planning before students begin tomorrow’s writing.',why:'Visible planning separates idea development from sentence production and demonstrates the strategic choices writers make.'},
  'write-a-paragraph-together':{promise:'Share the decisions of composing so students can participate in writing before doing it alone.',time:20,domains:['Listening','Speaking','Reading','Writing'],phase:'During',when:'After studying a model and before independent writing in a new genre or language pattern.',steps:['Agree on a clear purpose for the paragraph.','Invite several possible opening sentences.','Discuss and select language together.','Reread after each addition for meaning and flow.','Name decisions students can reuse independently.'],script:'“We have two good options. Which opening makes our main idea clearer to the reader, and why?”',mistake:'Writing students’ suggestions without discussing choices, or steering so heavily that the teacher authors everything.',try:'Co-write one short paragraph tomorrow and pause for three genuine language decisions.',why:'Joint construction places expert support inside the act of composing while preserving student contribution and agency.'},
  'use-a-checklist-while-revising':{promise:'Turn revision into a focused process students can perform rather than a vague instruction to improve.',time:15,domains:['Reading','Writing'],phase:'After',when:'After a meaningful draft exists and students need to revisit a few high-value features.',steps:['Limit the checklist to the lesson’s most important criteria.','Translate each criterion into observable language.','Model checking one item on a sample.','Have students revise one feature at a time.','End by naming an improvement, not merely ticking boxes.'],script:'“Our first check is meaning: can a reader identify the main idea? Underline where you made it clear.”',mistake:'Using a long generic checklist that mixes content, structure, spelling, and every grammar feature.',try:'Create a three-item checklist tied directly to tomorrow’s writing goal.',why:'A concise checklist externalizes revision decisions and supports learners to monitor their own work more independently.'},
  'give-feedback-on-meaning-before-grammar':{promise:'Protect students’ ideas and motivation while making feedback more focused and usable.',time:10,domains:['Writing'],phase:'After',when:'When responding to an early draft or to writing where extensive language errors could distract from the message.',steps:['Read first to understand the writer’s meaning.','Respond to one idea, strength, or question.','Identify the highest-value next step for communication.','Address a limited language feature only when it serves that goal.','Give time for the student to use the feedback.'],script:'“Your example makes the impact clear. Add one sentence explaining why it matters; then we’ll check the verb tense in that section.”',mistake:'Covering a draft in corrections before acknowledging or developing what the student is trying to say.',try:'On one draft tomorrow, write one meaning-focused response before marking any language feature.',why:'Meaning-first feedback treats multilingual learners as authors and prioritizes revisions with the greatest communicative impact.'},
  'compare-two-anonymous-student-samples':{promise:'Help students notice effective choices and possible improvements without evaluating a classmate publicly.',time:15,domains:['Reading','Speaking','Writing'],phase:'After',when:'Before revision or assessment, using carefully selected samples that illuminate the current success criteria.',steps:['Choose or construct two brief, respectful anonymous samples.','Read both first for meaning.','Ask students to notice a specific feature.','Compare effects using evidence from the text.','Apply one insight to current writing.'],script:'“Both writers answer the question. Which one helps the reader follow the reasoning more clearly? Point to the language that does that.”',mistake:'Setting up one sample as simply good and the other as bad, encouraging judgment rather than analysis.',try:'Prepare two short samples that solve the same writing problem differently and ask one focused comparison question.',why:'Comparative noticing makes quality visible and creates a shared language for revision without centering individual students.'},
  'name-and-celebrate-a-language-feature-in-student-writing':{promise:'Build writers’ identities by showing students exactly what their language already accomplishes.',time:5,domains:['Reading','Writing'],phase:'After',when:'During feedback, sharing, conferencing, or lesson closure when a student has made an effective language choice.',steps:['Select an authentic, meaningful feature.','Quote or point to the precise language.','Name what the writer did.','Explain its effect on the reader.','Invite the student or class to reuse the move.'],script:'“You repeated ‘we remember’ at the start of three sentences. That creates emphasis and gives the paragraph a strong rhythm.”',mistake:'Offering generic praise such as “great vocabulary” without helping the writer understand the successful choice.',try:'Choose one student sentence tomorrow and name the exact language move and its effect.',why:'Specific recognition builds metalinguistic awareness and positions multilingual learners as capable, intentional language users.'},
  'teach-students-to-use-bilingual-resources-effectively':{promise:'Help learners use dictionaries, translation tools, and bilingual texts thoughtfully rather than dependently.',time:15,domains:['Reading','Writing'],phase:'During',when:'When learners need to interpret, select, verify, or use words and phrases across languages.',steps:['Model the purpose and limits of one resource.','Search for a word or phrase in context.','Compare possible meanings rather than taking the first result.','Verify the choice in an example sentence or second source.','Use the selected language in the actual task.'],script:'“The translator gives three options. Which one fits our science sentence? Let’s check an example before choosing.”',mistake:'Banning translation entirely or accepting an unverified machine translation as automatically accurate.',try:'Model one context-checking routine with a bilingual resource before students use it independently.',why:'Strategic resource use develops autonomy and treats translation as a tool for reasoning rather than a shortcut that replaces it.'},
  'model-annotation-while-reading':{promise:'Show students how brief marks and notes can support thinking rather than decorate a page.',time:10,domains:['Reading','Writing'],phase:'During',when:'When students need to track ideas, questions, evidence, vocabulary, or changes in understanding through a text.',steps:['Choose one annotation purpose linked to the reading goal.','Model reading a short section before marking.','Add a brief symbol or note and explain why.','Continue reading to show how the annotation is used.','Let students annotate the next section with the same purpose.'],script:'“I’m writing ‘cause’ here because this sentence explains why the change happened. That note will help when I summarize.”',mistake:'Requiring many symbols or annotations without showing how they improve comprehension or later work.',try:'Teach one annotation code tomorrow and connect it to a task students will complete after reading.',why:'Purposeful annotation externalizes comprehension and leaves a usable trail of thinking for discussion and writing.'},
  'use-graphic-organizers-strategically':{promise:'Choose a visual structure that clarifies the thinking students must do—not just the topic.',time:15,domains:['Reading','Writing','Speaking'],phase:'During',when:'When learners need to organize relationships such as sequence, cause, comparison, hierarchy, or evidence and claim.',steps:['Name the thinking relationship in the task.','Choose the simplest organizer that represents it.','Model adding one idea and explaining its placement.','Let students adapt the organizer when useful.','Use the completed thinking in speaking or writing.'],script:'“This is a cause-and-effect task, so each arrow must explain a relationship—not simply connect two words.”',mistake:'Giving every student the same generic organizer or treating completion as the learning outcome.',try:'Match one organizer to the exact relationship in tomorrow’s task and plan how students will use it afterward.',why:'A well-matched organizer reduces organizational load and makes conceptual relationships available for further language production.'},
  'teach-students-to-ask-clarifying-questions':{promise:'Give learners safe, useful language for repairing confusion and staying engaged.',time:10,domains:['Listening','Speaking'],phase:'During',when:'Before complex directions, partner work, discussion, or any setting where students may understand only part of a message.',steps:['Normalize clarification as skilled learning behavior.','Teach two or three questions for different kinds of confusion.','Model asking and responding respectfully.','Rehearse with intentionally unclear examples.','Notice and reinforce clarification during authentic tasks.'],script:'“Could you repeat the last step?” “What does ___ mean here?” “Can you show me an example?”',mistake:'Telling students to ask questions while maintaining a classroom climate where confusion feels embarrassing.',try:'Teach one clarification question before tomorrow’s partner task and praise its first authentic use.',why:'Repair strategies support comprehension, agency, and sustained interaction when language or task demands create uncertainty.'},
  'model-productive-struggle':{promise:'Show learners how to stay with a challenging task and use resources before giving up.',time:10,domains:['Listening','Speaking','Reading','Writing'],phase:'During',when:'When students face an achievable challenge and need strategies for uncertainty rather than immediate answers.',steps:['Choose a genuinely challenging but accessible example.','Name what is confusing without performing helplessness.','Try one available strategy and evaluate it.','Try another route if the first does not help.','Reflect on which action moved the thinking forward.'],script:'“I don’t understand this sentence yet. I’ll reread the heading and look for a word I recognize before asking for another clue.”',mistake:'Romanticizing struggle, withholding necessary support, or confusing frustration with productive challenge.',try:'Think aloud through one manageable difficulty tomorrow and name two resources you use.',why:'Modeling strategic persistence makes help-seeking and uncertainty visible while showing that challenge should be supported, not endured indefinitely.'},
  'teach-students-to-self-assess-with-a-rubric':{promise:'Turn success criteria into a tool students can use to understand and improve their own work.',time:15,domains:['Reading','Speaking','Writing'],phase:'After',when:'After students have seen models and produced enough work to evaluate a specific criterion meaningfully.',steps:['Unpack one criterion in student-friendly language.','Examine examples at different levels.','Model making a judgment with evidence.','Have students highlight evidence in their own work.','Choose one specific next step.'],script:'“The criterion says ‘supports ideas with evidence.’ Point to where your evidence appears, then decide what would strengthen it.”',mistake:'Asking students to assign themselves a score without teaching what quality looks like or requiring evidence.',try:'Use one rubric row tomorrow and have students underline evidence before choosing a next step.',why:'Evidence-based self-assessment develops ownership and helps learners connect abstract criteria to concrete language choices.'},
  'set-language-goals-with-students':{promise:'Help learners choose a manageable language focus they can notice, practise, and revisit.',time:15,domains:['Listening','Speaking','Reading','Writing'],phase:'Before',when:'At the start of a unit, conference cycle, or recurring task where students can work toward an observable language behavior.',steps:['Review evidence from recent learning.','Identify a strength and a useful next area.','Co-write one specific, observable goal.','Choose a strategy and situation for practice.','Set a short time to revisit evidence of growth.'],script:'“You explain your ideas clearly. Your next goal could be adding evidence using ‘for example.’ Where will you practise that this week?”',mistake:'Assigning broad goals such as “improve English” that students cannot act on or evaluate.',try:'Conference with one student and turn a broad wish into one observable language action.',why:'Specific co-created goals connect reflection to deliberate practice while respecting learner agency and developmental readiness.'},
  'differentiate-one-task-in-three-ways':{promise:'Adjust access, process, and expression while keeping one ambitious learning goal.',time:20,domains:['Listening','Speaking','Reading','Writing'],phase:'Before',when:'During planning for a shared task when learners need different routes into the same essential thinking.',steps:['Name the non-negotiable learning goal.','Plan one access support for input.','Plan one process support for sense-making.','Offer more than one way to express learning.','Check that every version preserves the central cognitive demand.'],script:'“Everyone will explain the cause. Some will use the annotated text, some a diagram, and some the original source; all explanations need evidence.”',mistake:'Creating three different difficulty levels that quietly lower expectations for multilingual learners.',try:'Take one task and add one input support, one process support, and one expression option.',why:'Purposeful differentiation widens access to shared intellectual work without separating learners from the curriculum’s essential goals.'},
  'use-ai-responsibly-to-support-language-learning':{promise:'Use AI as a transparent support for practice and feedback—not as a replacement for thinking or authorship.',time:20,domains:['Listening','Speaking','Reading','Writing'],phase:'During',when:'When school policy permits and an AI tool can provide bounded language practice, examples, explanation, or revision support.',steps:['Define the learning purpose before choosing the tool.','Protect privacy and follow school policy.','Model a specific prompt and inspect the output critically.','Require students to verify, adapt, and explain what they use.','Keep evidence of the student’s own thinking and process.'],script:'“Ask for three possible transitions, then decide which one fits your relationship and explain why. Do not paste a rewritten paragraph.”',mistake:'Uploading personal data, treating generated language as authoritative, or allowing the tool to complete the intellectual work.',try:'Design one bounded AI use with no personal data, a verification step, and a visible student decision.',why:'Responsible use requires human judgment, privacy protection, transparency, and task design that keeps language learning and authorship with the learner.'},
  'scaffold-a-complex-classroom-discussion':{promise:'Open a demanding discussion to more learners without simplifying the ideas under consideration.',time:20,domains:['Listening','Speaking','Reading'],phase:'Before',when:'Before a discussion involving dense content, multiple perspectives, evidence, or unfamiliar academic interaction.',steps:['Clarify the intellectual purpose and final discussion question.','Build essential knowledge and preview a few high-value terms.','Provide time to read, annotate, or rehearse ideas.','Structure equitable participation and response moves.','Pause to synthesize, then fade supports as the conversation develops.'],script:'“Prepare one claim and one piece of evidence. In the first round, each person shares; in the second, respond to an idea you heard.”',mistake:'Reducing the question’s complexity or over-scripting every sentence until authentic exchange disappears.',try:'Prepare one complex question with a knowledge preview, private rehearsal, and a two-round participation structure.',why:'Layered preparation and interaction support preserve rigorous collective reasoning while reducing avoidable language and participation barriers.'},
  'reflect-with-students-on-language-growth':{promise:'Help learners recognize progress, understand what supported it, and choose a meaningful next step.',time:10,domains:['Listening','Speaking','Reading','Writing'],phase:'After',when:'After a unit, repeated task, conference cycle, presentation, or writing process with visible evidence over time.',steps:['Bring together two pieces of evidence from different moments.','Ask students to notice a specific change.','Name strategies or conditions that helped.','Celebrate growth without implying completion.','Choose one small next step and a place to practise it.'],script:'“Compare these two explanations. What can you do now that was harder before? What helped you make that change?”',mistake:'Reducing reflection to levels or scores instead of examining real language and learning processes.',try:'Ask students to compare one earlier and one recent response, then name a change and its cause.',why:'Evidence-based reflection develops metacognition, reinforces learner identity, and connects past success to future action.'},
  'celebrate-multilingualism-as-a-classroom-asset':{promise:'Build a classroom where languages are visible, intellectually valued, and connected to everyday learning.',time:15,domains:['Listening','Speaking','Reading','Writing'],phase:'During',when:'Across routines, displays, texts, discussions, family connections, and curriculum—not only during cultural celebrations.',steps:['Learn which languages and varieties students use.','Invite multilingual knowledge into meaningful academic tasks.','Represent languages accurately and with permission.','Highlight what cross-language comparison teaches the class.','Review whose language is visible, valued, and heard.'],script:'“Our class knows many ways to express this idea. What can those languages help all of us notice about the concept?”',mistake:'Using languages as decoration, tokenizing students, or asking an individual to represent an entire language or culture.',try:'Add one authentic multilingual contribution to tomorrow’s learning and connect it directly to the lesson goal.',why:'Sustained asset-based practice supports belonging and recognizes multilingual repertoires as resources for thinking, communication, and community.'},
  'create-an-anchor-chart-with-students':{promise:'Capture useful thinking and language with students so the chart becomes a tool they actually use.',time:15,domains:['Listening','Speaking','Reading','Writing'],phase:'During',when:'When a process, language pattern, or set of ideas will be used repeatedly across a lesson or unit.',steps:['Name the purpose of the chart and leave room for student contributions.','Model the first example while thinking aloud.','Invite students to suggest words, examples, visuals, or home-language connections.','Organize contributions into a simple structure students can scan.','Refer to the chart during practice and revise it as understanding grows.'],script:'“This chart is for us to use, not just to look at. What should we add so it helps someone explain their thinking?”',mistake:'Arriving with a polished poster that students did not help construct, then never referring to it during the task.',try:'Start one chart with only a heading and a single example. Add three student contributions during tomorrow’s lesson.',why:'Co-constructing a visual record makes classroom thinking visible and gives learners a shared, accessible language resource.'},
  'end-with-a-two-minute-oral-recap':{promise:'Help learners retrieve the lesson’s key idea and say it in their own words before they leave.',time:5,domains:['Listening','Speaking'],phase:'After',when:'At the end of a lesson, transition, or learning sequence when you want a fast check of meaning and language.',steps:['Return to the lesson’s content and language goals.','Give students ten quiet seconds to choose the most important idea.','Provide one optional recap stem or three key words.','Have every student recap to a partner in 30–45 seconds.','Listen for one strength and one idea to revisit next lesson.'],script:'“In one or two sentences, tell your partner what mattered most today and why. You can begin, ‘The key idea was…’”',mistake:'Using the recap only with volunteers. The value comes from every learner retrieving and rehearsing the learning.',try:'Reserve the final two minutes tomorrow. Display one stem and ask every student to give a spoken recap.',why:'Brief retrieval and oral formulation help consolidate meaning while giving the teacher immediate evidence of what students understood.'},
  'teach-accountable-talk-stems':{promise:'Give students flexible language for explaining, questioning, and building ideas together.',time:10,domains:['Listening','Speaking'],phase:'Before',when:'Before a discussion in which students need to respond to one another rather than speak only to the teacher.',steps:['Choose one discussion function students need, such as clarify, justify, or build on.','Introduce only two or three stems for that function.','Model a natural exchange with a student or teaching partner.','Let pairs rehearse with low-risk content.','Keep the stems visible, then notice and name when students use them purposefully.'],script:'“If you want to build on an idea, you might say, ‘I’d like to add…’ Use the stem if it helps; change it if you have another way.”',mistake:'Displaying a large list of stems without teaching when or why a speaker would choose each one.',try:'Choose one conversational move tomorrow—clarify, justify, or build on—and teach two ways to say it.',why:'Functional language makes the social expectations of academic discussion more visible while preserving students’ choice and voice.'},
  'model-think-pair-share':{promise:'Turn a familiar routine into genuine thinking, rehearsal, and inclusive participation.',time:10,domains:['Listening','Speaking'],phase:'During',when:'When a question deserves more than a quick volunteer response and every learner should develop an answer.',steps:['Ask one focused question and show it visually.','Model what productive private thinking might look like.','Give quiet think time before anyone speaks.','Structure the pair exchange so both partners contribute.','Invite ideas into the whole class without making public sharing the only measure of participation.'],script:'“Think first—no hands yet. Decide on one idea and why you think it. Then each partner will have thirty seconds to share.”',mistake:'Skipping the think stage or allowing one partner to dominate, turning the routine into informal pair chat.',try:'Plan one worthwhile question and write the timing beside it: think 15 seconds, partner A 30, partner B 30.',why:'A predictable sequence gives learners time to formulate language, test an idea privately, and enter whole-class meaning-making with greater confidence.'},
  'use-structured-partner-talk':{promise:'Make partner talk equitable, purposeful, and easier to listen to—not just easier to start.',time:10,domains:['Listening','Speaking'],phase:'During',when:'When students need sustained oral practice, idea development, or collaborative reasoning with a clear outcome.',steps:['State the purpose and the product of the conversation.','Assign a simple sequence or role to each partner.','Provide only the language support the task requires.','Set a visible time limit and a listening responsibility.','Close with a product: a shared idea, question, summary, or point of difference.'],script:'“Partner A explains one reason. Partner B listens for the evidence, then asks one question. Together, choose the clearest explanation.”',mistake:'Telling students merely to “discuss” without defining what each person should contribute or produce.',try:'Replace one “talk to your partner” instruction with a two-role exchange and one shared outcome.',why:'Clear participation structures distribute airtime and make both speaking and listening necessary to complete the intellectual task.'},
  'teach-agree-disagree-and-build-on-language':{promise:'Help students respond to ideas respectfully while making their own reasoning clearer.',time:10,domains:['Listening','Speaking'],phase:'Before',when:'Before discussion, debate, interpretation, or problem solving where students will compare different claims or approaches.',steps:['Teach agreement as more than saying yes: students should name what they agree with.','Model respectful disagreement focused on the idea, not the person.','Add one way to build on or qualify a peer’s contribution.','Rehearse using neutral, low-stakes examples.','Prompt students to include a reason or evidence during the real discussion.'],script:'“I see it differently because…” or “I agree with your point about ___. I’d add…”',mistake:'Treating the stems as politeness formulas without requiring students to listen closely or explain their reasoning.',try:'Post one agree, one disagree, and one build-on phrase. Model all three before tomorrow’s discussion.',why:'Explicit response language supports relational safety and helps learners connect their contribution to the developing conversation.'},
  'use-a-speaking-routine-where-everyone-participates':{promise:'Replace volunteer-only discussion with a predictable routine that gives every learner a voice.',time:10,domains:['Listening','Speaking'],phase:'During',when:'When the same few students usually answer or when you need broad participation before assessing class understanding.',steps:['Choose a simple routine with simultaneous or sequential participation.','Pose a question worth answering and allow quiet preparation.','Make the order, time, and listening expectation clear.','Allow students to pass once or use notes when appropriate.','Sample ideas afterward without ranking speed or confidence.'],script:'“Everyone will contribute one idea. You may use your notes, repeat an idea in your own words, or pass once and return.”',mistake:'Calling a routine inclusive while putting unprepared learners on the spot or rewarding only rapid spoken English.',try:'Use a round-robin in groups of four tomorrow. Give everyone 20 seconds to prepare one contribution first.',why:'Predictable participation broadens access to classroom talk and gives more learners the practice needed to develop fluency and confidence.'},
  'prompt-students-to-expand-answers':{promise:'Help students turn brief responses into clearer, more precise explanations without taking over their thinking.',time:5,domains:['Listening','Speaking'],phase:'During',when:'When a learner has the core idea but needs support to add a reason, example, detail, connection, or academic term.',steps:['Acknowledge the meaning already present in the response.','Choose one expansion move that fits the idea.','Ask a short prompt such as “What makes you think that?” or “Can you give an example?”','Wait while the student formulates the addition.','Revoice the expanded idea only if useful, then return ownership to the student.'],script:'“That gives us the main idea. Can you add one example that would help us picture what you mean?”',mistake:'Firing several questions at once or replacing the student’s answer with the fuller answer you wanted.',try:'Write one expansion prompt on tomorrow’s plan. Use it after a brief but meaningful student response, then wait.',why:'Focused prompting treats an initial response as a starting point and supports learners to express more complex thinking in manageable steps.'},
  'gradually-remove-scaffolds':{promise:'Move learners toward independence while keeping the intellectual challenge high.',time:10,domains:['Speaking','Reading','Writing'],phase:'After',when:'When students can complete a task with support and need a deliberate next step toward doing more on their own.',steps:['Identify exactly what the scaffold is currently doing.','Look for evidence that students are ready for less support.','Remove or loosen one element at a time.','Keep the learning goal and cognitive demand unchanged.','Notice what students can now do and restore support temporarily if needed.'],script:'“Last time we used a full frame. Today you’ll choose from three sentence starters—or try your own structure.”',mistake:'Removing every support at once or keeping scaffolds so long that they become a ceiling.',try:'Choose one familiar scaffold and reduce it by one step for students who are ready.',why:'Responsive fading keeps support temporary and purposeful, helping learners take ownership without experiencing an abrupt access cliff.'}
};

const savedStore='lingua-strategies-saved';
let strategies=[],visible=9,query='',category='',saved=new Set(JSON.parse(localStorage.getItem(savedStore)||localStorage.getItem('strategy-flow-saved')||'[]'));
const $=s=>document.querySelector(s);
const generic=s=>({promise:`A practical way to strengthen ${s.category.toLowerCase()} while keeping every learner involved.`,time:s.category==='Writing'?15:10,domains:s.category==='Writing'?['Speaking','Writing']:s.category==='Reading'?['Reading']:['Listening','Speaking'],phase:'During',when:`Use this when learners need more structure, access, or independence with ${s.title.toLowerCase()}.`,steps:[`Name the learning purpose and introduce ${s.title.toLowerCase()} briefly.`,'Model one clear example while students notice what you do.','Let students try with a partner before working independently.','Listen and observe; adjust the support without lowering the goal.','Close by naming what helped and when students can use it again.'],script:`“Watch how I ${s.title.toLowerCase()}. Then you’ll try it with a partner before doing it on your own.”`,mistake:'Using the routine without connecting it to a clear learning purpose or checking what students actually do with it.',try:`Choose one moment in tomorrow’s lesson to ${s.title.toLowerCase()}. Keep the first attempt brief and notice who participates.`,why:'This practical adaptation supports access and participation. Add research or framework citations only after they have been reviewed and sourced.'});
const content=s=>locale==='zh'?{...deepContent[s.slug],...zhContent[s.slug],domains:deepContent[s.slug].domains,phase:deepContent[s.slug].phase,time:deepContent[s.slug].time}:{...generic(s),...deepContent[s.slug]};
const titleOf=s=>locale==='zh'?zhContent[s.slug].title:s.title;
const categoryOf=c=>locale==='zh'?zhUI.categories[c]:c;
const phaseOf=p=>locale==='zh'?zhUI.phases[p]:p;
const domainOf=d=>locale==='zh'?zhUI.domains[d]:d;

async function init(){
  try{const response=await fetch('data/strategies.json');if(!response.ok)throw new Error();strategies=await response.json();applyLocale();updateSaved();}
  catch{$('#strategyGrid').innerHTML='<div class="empty-state"><h3>The strategy library could not load.</h3><p>Please open this site through a local web server, then refresh.</p></div>';}
}
function renderNeeds(){const list=locale==='zh'?zhNeeds:needs;$('#needsGrid').innerHTML=list.map(n=>`<button class="need-card" data-query="${n.query}" data-label="${n.label}"><span class="icon">${n.icon}</span><h3>${n.label}</h3><small>${locale==='zh'?zhUI.findMoves:'Find useful moves →'}</small></button>`).join('');document.querySelectorAll('.need-card').forEach(b=>b.onclick=()=>selectNeed(b.dataset.query,b.dataset.label));}
function selectNeed(value,label=value){query=value;category='';visible=9;$('#searchInput').value=label;renderFilters();render();$('#strategies').scrollIntoView({behavior:'smooth'});}
function renderFilters(){const cats=[...new Set(strategies.map(s=>s.category))];$('#categoryFilters').innerHTML=cats.map(c=>`<button class="filter-chip ${category===c?'active':''}" data-category="${c}">${categoryOf(c)}</button>`).join('');document.querySelectorAll('.filter-chip').forEach(b=>b.onclick=()=>{category=category===b.dataset.category?'':b.dataset.category;visible=9;renderFilters();render();});$('#activeFilterCount').textContent=category?1:0;}
function getFiltered(){const q=query.trim().toLowerCase();return strategies.filter(s=>{const z=zhContent[s.slug];const hay=[s.title,s.category,deepContent[s.slug].promise,z.title,z.promise,categoryOf(s.category)].join(' ').toLowerCase();return(!q||hay.includes(q))&&(!category||s.category===category);});}
function render(){const filtered=getFiltered();const cards=filtered.slice(0,visible);$('#resultSummary').textContent=locale==='zh'?zhUI.results(filtered.length):`${filtered.length} ${filtered.length===1?'strategy':'strategies'} to help you move forward.`;$('#strategyGrid').innerHTML=cards.map(cardHTML).join('');$('#emptyState').hidden=filtered.length>0;$('#loadMore').hidden=visible>=filtered.length||filtered.length===0;bindCards();}
function cardHTML(s){const c=content(s);return `<article class="strategy-card" tabindex="0" data-slug="${s.slug}"><div class="card-top"><span class="tag">${categoryOf(s.category)}</span><button class="save-icon ${saved.has(s.slug)?'saved':''}" data-save="${s.slug}" aria-label="${saved.has(s.slug)?'Remove from':'Save to'} saved strategies">${saved.has(s.slug)?'♥':'♡'}</button></div><h3>${titleOf(s)}</h3><p>${c.promise}</p><div class="card-meta"><span>◷ ${c.time} ${locale==='zh'?zhUI.minutes:'min'}</span><span>${phaseOf(c.phase)}</span><span class="card-arrow">→</span></div></article>`;}
function bindCards(){document.querySelectorAll('[data-save]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleSave(b.dataset.save);});document.querySelectorAll('.strategy-card').forEach(c=>{c.onclick=()=>openStrategy(c.dataset.slug);c.onkeydown=e=>{if(e.key==='Enter')openStrategy(c.dataset.slug);};});}
function toggleSave(slug){saved.has(slug)?saved.delete(slug):saved.add(slug);localStorage.setItem(savedStore,JSON.stringify([...saved]));updateSaved();render();showToast(locale==='zh'?(saved.has(slug)?'已收藏':'已取消收藏'):(saved.has(slug)?'Saved for later':'Removed from saved'));}
function updateSaved(){$('#savedCount').textContent=saved.size;}
function openStrategy(slug){const s=strategies.find(x=>x.slug===slug),c=content(s),u=locale==='zh'?zhUI:null;$('#dialogContent').innerHTML=`<div class="dialog-shell"><button class="dialog-close" aria-label="Close">×</button><div class="dialog-kicker">${categoryOf(s.category)} · ${u?u.expanded:'Expanded guide'}</div><h2 id="dialogTitle">${titleOf(s)}</h2><p class="dialog-lead">${c.promise}</p><div class="dialog-meta"><span>◷ ${c.time} ${u?u.minutes:'minutes'}</span><span>${phaseOf(c.phase)}</span>${c.domains.map(d=>`<span>${domainOf(d)}</span>`).join('')}</div><div class="tabs"><button class="tab active" data-tab="quick">${u?u.quickTab:'Quick version'}</button><button class="tab" data-tab="deep">${u?u.deepTab:'Go deeper'}</button></div><div class="panel" data-panel="quick"><h3>${u?u.when:'When to use it'}</h3><p>${c.when}</p><h3>${u?u.how:'How to do it'}</h3><ol class="steps">${c.steps.map(x=>`<li>${x}</li>`).join('')}</ol><h3>${u?u.words:'Words you could use'}</h3><div class="script">${c.script}</div><div class="try-box"><span class="kicker">${u?u.tryTomorrow:'Try this tomorrow'}</span><h3>${u?u.oneStep:'One small next step'}</h3><p>${c.try}</p><button class="light-button" data-save="${s.slug}">${saved.has(s.slug)?(u?u.savedTomorrow:'Saved for tomorrow ✓'):(u?u.save:'Save for tomorrow')}</button></div></div><div class="panel" data-panel="deep" hidden><h3>${u?u.why:'Why this works'}</h3><p>${c.why}</p><h3>${u?u.misstep:'A common misstep'}</h3><p>${c.mistake}</p><h3>${u?u.notice:'What to notice'}</h3><p>${u?u.noticeText:'Notice who participates, how much language students produce, and whether the support helps them do more of the thinking themselves.'}</p><h3>${u?u.reflect:'Reflect for two minutes'}</h3><p>${u?u.reflectText:'What became possible for learners with this support? What could you keep, adapt, or fade next time?'}</p></div></div>`;const d=$('#strategyDialog');d.showModal();$('.dialog-close').onclick=()=>d.close();document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===t));document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==t.dataset.tab);});$('#dialogContent [data-save]').onclick=()=>{toggleSave(s.slug);openStrategy(s.slug);};}
function applyLocale(){document.documentElement.lang=locale==='zh'?'zh-CN':'en';document.title=locale==='zh'?'Lingua Strategies｜多语言课堂教学策略':'Lingua Strategies — Know what to try tomorrow';document.querySelectorAll('[data-en][data-zh]').forEach(el=>el.innerHTML=el.dataset[locale]);document.querySelectorAll('[data-locale]').forEach(b=>b.classList.toggle('active',b.dataset.locale===locale));$('#savedLabel').textContent=locale==='zh'?zhUI.saved:'Saved';$('#filterLabel').textContent=locale==='zh'?zhUI.filters:'Filters';$('#searchInput').placeholder=locale==='zh'?'搜索课堂问题或教学策略…':'Search a classroom problem or strategy…';$('#clearFilters').textContent=locale==='zh'?'清除筛选':'Clear filters';$('#emptyState h3').textContent=locale==='zh'?zhUI.noMatch:'No exact match yet';$('#emptyState p').textContent=locale==='zh'?zhUI.noMatchHelp:'Try a broader word like “talk”, “writing”, or “scaffold”.';$('#resetSearch').textContent=locale==='zh'?zhUI.showAll:'Show all strategies';query='';category='';visible=9;$('#searchInput').value='';renderNeeds();renderFilters();render();}
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),1800);}
document.querySelectorAll('[data-locale]').forEach(b=>b.onclick=()=>{locale=b.dataset.locale;localStorage.setItem('lingua-strategies-language',locale);applyLocale();});$('#searchInput').oninput=e=>{query=e.target.value;visible=9;render();};$('#filterToggle').onclick=()=>{const p=$('#filterPanel');p.hidden=!p.hidden;$('#filterToggle').setAttribute('aria-expanded',String(!p.hidden));};$('#clearFilters').onclick=()=>{category='';renderFilters();render();};$('#loadMore').onclick=()=>{visible+=9;render();};$('#resetSearch').onclick=()=>{query='';category='';$('#searchInput').value='';renderFilters();render();};$('#starterButton').onclick=()=>selectNeed('visual',locale==='zh'?'支持新加入的学生':'visual');$('#savedButton').onclick=()=>{query='';category='';const filtered=strategies.filter(s=>saved.has(s.slug));visible=100;$('#searchInput').value='';$('#strategyGrid').innerHTML=filtered.length?filtered.map(cardHTML).join(''):`<div class="empty-state"><h3>${locale==='zh'?zhUI.emptySaved:'Nothing saved yet'}</h3><p>${locale==='zh'?zhUI.emptySavedHelp:'Tap the heart on a strategy to keep it here for tomorrow.'}</p></div>`;$('#resultSummary').textContent=locale==='zh'?`已收藏 ${filtered.length} 个策略`:`${filtered.length} saved ${filtered.length===1?'strategy':'strategies'}.`;$('#loadMore').hidden=true;bindCards();$('#strategies').scrollIntoView({behavior:'smooth'});};$('#strategyDialog').addEventListener('click',e=>{if(e.target===$('#strategyDialog'))$('#strategyDialog').close();});
init();
